/* @autogenerated */
package net.civeira.phylax.feature.oauth.authentication.domain;

import java.util.List;

/**
 * Authentication modes and their ACR values.
 *
 * Responsibilities: - Provide a mapping from mode to ACR value. - Standardize authentication
 * strength labels.
 *
 * Design notes: - Used for token claims and audit reporting. - Values are aligned with configured
 * policy.
 */
public enum AuthenticationMode {

  SESSION("0"), PASSWORD("1"), MFA("2"), REFRESH("0"), CODE_EXCHANGE("0");

  /**
   * Authentication context class reference value.
   */
  private final String acr;

  private AuthenticationMode(String acr) {
    this.acr = acr;
  }

  /**
   * Returns the ACR value for the mode.
   *
   * Used when constructing token claims and audit data. The returned value is a short policy
   * identifier.
   *
   * @return ACR value string
   */
  public String getAcr() {
    return acr;
  }

  /**
   * Authentication methods (RFC 8176) proven by an authentication in this mode alone.
   *
   * Only a password check and a second factor prove something; the other modes reuse an earlier
   * authentication, whose methods travel with the session, code or refresh token.
   *
   * @return the methods, empty for the modes that prove nothing by themselves
   */
  public List<String> amr() {
    return switch (this) {
      case PASSWORD -> List.of("pwd");
      case MFA -> List.of("pwd", "otp", "mfa");
      default -> List.of();
    };
  }
}
